keyConcepts.codeExample:
-- Sans protection : condition de course possible
SELECT stock FROM products WHERE id = 17; -- lit 1
UPDATE products SET stock = stock - 1 WHERE id = 17;

-- Avec transaction et verrou de ligne
BEGIN;
SELECT stock FROM products WHERE id = 17 FOR UPDATE;
-- une deuxième transaction concurrente attend ici
UPDATE products SET stock = stock - 1 WHERE id = 17 AND stock > 0;
COMMIT;
-- si stock était déjà à 0, l'UPDATE ne touche aucune ligne :
-- l'application vérifie le rowcount et refuse la vente
